WITH with_windows AS (SELECT id, order_id, product_id, quantity, unit_price, CORR(quantity, unit_price) OVER w_hist AS corr_quantity_unit_price, LEAD(quantity, 2) OVER w_ordered AS next_quantity, FIRST_VALUE(quantity) IGNORE NULLS OVER w_grp AS first_known_quantity FROM order_items WINDOW w_hist AS (PARTITION BY order_id, product_id), w_ordered AS (PARTITION BY order_id, product_id ORDER BY unit_price, id), w_grp AS (PARTITION BY product_id ORDER BY quantity, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) SELECT CASE WHEN quantity >= 8 THEN 'PREMIUM' ELSE 'STANDARD' END AS quantity_tier, order_id, STDDEV_SAMP(unit_price) AS unit_price_stddev, APPROX_PERCENTILE(next_quantity, ARRAY(0.25, 0.5, 0.75)) AS next_quantity_quartiles, GROUPING(CASE WHEN quantity >= 8 THEN 'PREMIUM' ELSE 'STANDARD' END) AS gid FROM with_windows GROUP BY GROUPING SETS ((CASE WHEN quantity >= 8 THEN 'PREMIUM' ELSE 'STANDARD' END, order_id), (CASE WHEN quantity >= 8 THEN 'PREMIUM' ELSE 'STANDARD' END), ()) HAVING unit_price_stddev > 0 ORDER BY order_id DESC
